quotes=[]
def take(id,sid,pages,start,end,locator):
    r=source(sid);file=(S/r['local']).resolve()
    if file.suffix=='.pdf':
        d=fitz.open(file);text=' '.join(norm(d[p-1].get_text()) for p in pages)
    else:text=norm(BeautifulSoup(file.read_text(),'html.parser').get_text(' '))
    try:
        a=text.index(start);b=text.index(end,a)+len(end)
    except ValueError:
        print('MISSING',id,sid,pages,repr(start),repr(end));return
    quotes.append(dict(id=id,source_id=sid,source_file=str(file.relative_to(R)),pages=pages,text=text[a:b],locator=locator,normalization='Whitespace, punctuation spacing and line-end hyphenation only; wording retained.'))

